/// <summary>
/// returns the first WrkCtrId for Resource/resource group that is used for job scheduling
/// </summary>
/// <param name = "_prodRoute">ProdRoute</param>
/// <returns>WrkCtrId</returns>
public display WrkCtrId avaDisplayFirstResourceId(ProdRoute _prodRoute)
{
    WrkCtrRouteOprActivity          locWrkCtrRouteOprActivity;
    WrkCtrActivityRequirementSet    locWrkCtrActivityRequirementSet;
    WrkCtrActivityRequirement       locWrkCtrActivityRequirement;
    RouteOpr                        locRouteOpr = element.routeInventForm.findRouteOpr(_prodRoute);

    select firstonly locWrkCtrActivityRequirement
        join locWrkCtrActivityRequirementSet
        join locWrkCtrRouteOprActivity
        where locWrkCtrActivityRequirement.ActivityRequirementSet == locWrkCtrActivityRequirementSet.RecId
        && locWrkCtrActivityRequirement.UsedForJobScheduling == NoYes::Yes
        &&	locWrkCtrActivityRequirementSet.Activity == locWrkCtrRouteOprActivity.Activity
        && 	locWrkCtrRouteOprActivity.RouteOpr == locRouteOpr.RecId;

    switch(locWrkCtrActivityRequirement.subType().TableId)
    {
        case tableNum(WrkCtrActivityResourceRequirement):
        case tableNum(WrkCtrActivityResourceGroupRequirement):
            return locWrkCtrActivityRequirement.subtype().avaDisplayWrkCtrId();

        default:
            return '';
    }

}

/// <summary>
/// edit method for the LoadPercent field in the WrkCtrActivityRequirementSet record 
/// </summary>
/// <param name = "_set">boolean</param>
/// <param name = "_prodRoute">ProdRoute</param>
/// <param name = "_loadPercent">WrkCtrLoadPct</param>
/// <returns>WrkCtrLoadPct</returns>
public edit WrkCtrLoadPct avaEditWrkCtrLoadPct(boolean _set, ProdRoute _prodRoute, WrkCtrLoadPct _loadPercent)
{
    WrkCtrRouteOprActivity          locWrkCtrRouteOprActivity;
    WrkCtrActivityRequirementSet    locWrkCtrActivityRequirementSet;
    RouteOpr                        locRouteOpr = element.routeInventForm.findRouteOpr(_prodRoute);

    select forUpdate firstonly  locWrkCtrActivityRequirementSet
        join locWrkCtrRouteOprActivity
        where locWrkCtrActivityRequirementSet.Activity == locWrkCtrRouteOprActivity.Activity
        && 	locWrkCtrRouteOprActivity.RouteOpr == locRouteOpr.RecId;

    if (_set)
    {
        ttsbegin;
        locWrkCtrActivityRequirementSet.LoadPercent = _loadPercent;
        locWrkCtrActivityRequirementSet.update();
        ttscommit;
    }
    else
    {
        return locWrkCtrActivityRequirementSet.LoadPercent;
    }

    return _loadPercent;
}
